#!/usr/bin/env python3
"""Offline compiler from policy bundles to canonical minimal DFAs."""

import sys
import json
import math
from collections import deque


class WireError(Exception):
    def __init__(self, code):
        self.code = code


# ---------------------------------------------------------------------------
# Parsing / validation
# ---------------------------------------------------------------------------

def depth_within_limit(text):
    """Preliminary nesting scan. Returns False if depth ever exceeds 64."""
    depth = 0
    in_str = False
    esc = False
    for ch in text:
        if in_str:
            if esc:
                esc = False
            elif ch == '\\':
                esc = True
            elif ch == '"':
                in_str = False
        else:
            if ch == '"':
                in_str = True
            elif ch == '{' or ch == '[':
                depth += 1
                if depth > 64:
                    return False
            elif ch == '}' or ch == ']':
                if depth > 0:
                    depth -= 1
    return True


def decode_json(text):
    def pairs_hook(pairs):
        d = {}
        for k, v in pairs:
            if k in d:
                raise WireError('E_JSON')
            d[k] = v
        return d

    def parse_const(s):
        raise WireError('E_JSON')

    def parse_float(s):
        v = float(s)
        if v != v or v == float('inf') or v == float('-inf'):
            raise WireError('E_JSON')
        return v

    try:
        return json.loads(text, object_pairs_hook=pairs_hook,
                          parse_constant=parse_const, parse_float=parse_float)
    except WireError:
        raise
    except Exception:
        raise WireError('E_JSON')


def has_surrogate(s):
    for ch in s:
        o = ord(ch)
        if 0xD800 <= o <= 0xDFFF:
            return True
    return False


def check_unicode(obj):
    stack = [obj]
    while stack:
        x = stack.pop()
        if isinstance(x, str):
            if has_surrogate(x):
                raise WireError('E_SCHEMA')
        elif isinstance(x, dict):
            for k, v in x.items():
                stack.append(k)
                stack.append(v)
        elif isinstance(x, list):
            stack.extend(x)


class Stats:
    __slots__ = ('nodes', 'atoms', 'max_args', 'max_pathlen')

    def __init__(self):
        self.nodes = 0
        self.atoms = set()
        self.max_args = 0
        self.max_pathlen = 0


def expr_schema(e, service_set, stats):
    if not isinstance(e, dict):
        raise WireError('E_SCHEMA')
    stats.nodes += 1
    if 'op' not in e:
        raise WireError('E_SCHEMA')
    op = e['op']
    if not isinstance(op, str):
        raise WireError('E_SCHEMA')
    if op == 'true' or op == 'false':
        if set(e.keys()) != {'op'}:
            raise WireError('E_SCHEMA')
    elif op in ('match', 'startswith', 'endswith', 'contains'):
        if set(e.keys()) != {'op', 'path'}:
            raise WireError('E_SCHEMA')
        path = e['path']
        if not isinstance(path, list):
            raise WireError('E_SCHEMA')
        for tok in path:
            if not isinstance(tok, str):
                raise WireError('E_SCHEMA')
            if tok not in service_set:
                raise WireError('E_SCHEMA')
        if len(path) > stats.max_pathlen:
            stats.max_pathlen = len(path)
        stats.atoms.add((op, tuple(path)))
    elif op == 'not':
        if set(e.keys()) != {'op', 'arg'}:
            raise WireError('E_SCHEMA')
        expr_schema(e['arg'], service_set, stats)
    elif op == 'and' or op == 'or':
        if set(e.keys()) != {'op', 'args'}:
            raise WireError('E_SCHEMA')
        args = e['args']
        if not isinstance(args, list):
            raise WireError('E_SCHEMA')
        if len(args) > stats.max_args:
            stats.max_args = len(args)
        for a in args:
            expr_schema(a, service_set, stats)
    else:
        raise WireError('E_SCHEMA')


def validate_request(data):
    check_unicode(data)
    if not isinstance(data, dict):
        raise WireError('E_SCHEMA')
    if set(data.keys()) != {'services', 'rules', 'queries'}:
        raise WireError('E_SCHEMA')
    services = data['services']
    rules = data['rules']
    queries = data['queries']

    # ---- schema ----
    if not isinstance(services, list):
        raise WireError('E_SCHEMA')
    seen = set()
    for s in services:
        if not isinstance(s, str):
            raise WireError('E_SCHEMA')
        if s == '':
            raise WireError('E_SCHEMA')
        if s in seen:
            raise WireError('E_SCHEMA')
        seen.add(s)
    service_set = seen

    if not isinstance(rules, list):
        raise WireError('E_SCHEMA')
    stats = Stats()
    for rule in rules:
        if not isinstance(rule, dict):
            raise WireError('E_SCHEMA')
        if set(rule.keys()) != {'action', 'when'}:
            raise WireError('E_SCHEMA')
        act = rule['action']
        if not isinstance(act, str) or act not in ('allow', 'drop'):
            raise WireError('E_SCHEMA')
        expr_schema(rule['when'], service_set, stats)

    if not isinstance(queries, list):
        raise WireError('E_SCHEMA')
    for q in queries:
        if not isinstance(q, list):
            raise WireError('E_SCHEMA')
        for tok in q:
            if not isinstance(tok, str):
                raise WireError('E_SCHEMA')
            if tok not in service_set:
                raise WireError('E_SCHEMA')

    # ---- size limits ----
    if len(services) > 24:
        raise WireError('E_LIMIT')
    for s in services:
        if len(s) > 64:
            raise WireError('E_LIMIT')
    if len(rules) > 32:
        raise WireError('E_LIMIT')
    if len(queries) > 256:
        raise WireError('E_LIMIT')
    total_q = 0
    for q in queries:
        if len(q) > 4096:
            raise WireError('E_LIMIT')
        total_q += len(q)
    if total_q > 16384:
        raise WireError('E_LIMIT')
    if stats.nodes > 256:
        raise WireError('E_LIMIT')
    if stats.max_args > 32:
        raise WireError('E_LIMIT')
    if stats.max_pathlen > 16:
        raise WireError('E_LIMIT')
    if len(stats.atoms) > 10:
        raise WireError('E_LIMIT')

    return services, rules, queries, stats


# ---------------------------------------------------------------------------
# Atomic monitors
# ---------------------------------------------------------------------------

def build_prefix_table(pat):
    m = len(pat)
    pi = [0] * m
    k = 0
    for i in range(1, m):
        while k > 0 and pat[i] != pat[k]:
            k = pi[k - 1]
        if pat[i] == pat[k]:
            k += 1
        pi[i] = k
    return pi


def build_monitor(op, pat, A):
    """Return (init_state, true_state, transition_table)."""
    m = len(pat)
    if op == 'match':
        fail = m + 1
        n = m + 2
        trans = [[fail] * A for _ in range(n)]
        for k in range(m):
            trans[k][pat[k]] = k + 1
        return 0, m, trans
    if op == 'startswith':
        fail = m + 1
        n = m + 2
        trans = [[fail] * A for _ in range(n)]
        for k in range(m):
            trans[k][pat[k]] = k + 1
        trans[m] = [m] * A
        return 0, m, trans
    # endswith / contains
    if m == 0:
        return 0, 0, [[0] * A]
    pi = build_prefix_table(pat)
    n = m + 1
    trans = [[0] * A for _ in range(n)]

    def step(k, c):
        while True:
            if k < m and pat[k] == c:
                return k + 1
            if k == 0:
                return 0
            k = pi[k - 1]

    if op == 'endswith':
        for k in range(n):
            row = trans[k]
            for c in range(A):
                row[c] = step(k, c)
        return 0, m, trans
    else:  # contains
        for k in range(m):
            row = trans[k]
            for c in range(A):
                row[c] = step(k, c)
        trans[m] = [m] * A
        return 0, m, trans


# ---------------------------------------------------------------------------
# Product construction & complexity check
# ---------------------------------------------------------------------------

COMPLEXITY_CAP = 20000


def build_product(atoms, service_index, A):
    monitors = []
    for op, path in atoms:
        pat = [service_index[t] for t in path]
        monitors.append(build_monitor(op, pat, A))

    natoms = len(monitors)
    init = tuple(mo[0] for mo in monitors)
    true_states = [mo[1] for mo in monitors]
    tables = [mo[2] for mo in monitors]

    state_id = {init: 0}
    states = [init]
    rows = []
    dq = deque([0])
    while dq:
        sid = dq.popleft()
        tup = states[sid]
        row = [0] * A
        for c in range(A):
            nt = tuple(tables[i][tup[i]][c] for i in range(natoms))
            j = state_id.get(nt)
            if j is None:
                j = len(states)
                if j >= COMPLEXITY_CAP:
                    raise WireError('E_COMPLEXITY')
                state_id[nt] = j
                states.append(nt)
                dq.append(j)
            row[c] = j
        rows.append(row)

    # accept per state
    accept = []
    for tup in states:
        truth = [tup[i] == true_states[i] for i in range(natoms)]
        accept.append(evaluate(global_tree, truth))
    return rows, accept


# ---------------------------------------------------------------------------
# Expression tree
# ---------------------------------------------------------------------------

# nodes are tuples:
#   ('const', bool)
#   ('atom', index)
#   ('not', child)
#   ('and', [children]) / ('or', [children])

def build_tree(e, atom_index):
    op = e['op']
    if op == 'true':
        return ('const', True)
    if op == 'false':
        return ('const', False)
    if op in ('match', 'startswith', 'endswith', 'contains'):
        return ('atom', atom_index[(op, tuple(e['path']))])
    if op == 'not':
        return ('not', build_tree(e['arg'], atom_index))
    if op == 'and':
        return ('and', [build_tree(a, atom_index) for a in e['args']])
    return ('or', [build_tree(a, atom_index) for a in e['args']])


def evaluate(node, truth):
    op = node[0]
    if op == 'const':
        return node[1]
    if op == 'atom':
        return truth[node[1]]
    if op == 'not':
        return not evaluate(node[1], truth)
    if op == 'and':
        for ch in node[1]:
            if not evaluate(ch, truth):
                return False
        return True
    # or
    for ch in node[1]:
        if evaluate(ch, truth):
            return True
    return False


global_tree = None


# ---------------------------------------------------------------------------
# DFA minimization (Hopcroft)
# ---------------------------------------------------------------------------

def hopcroft(n, A, trans, accept):
    if n <= 1:
        blocks = {0: set(range(n))}
        block_of = [0] * n
        return blocks, block_of

    # predecessor lists
    pred = [[[] for _ in range(n)] for _ in range(A)]
    for s in range(n):
        row = trans[s]
        for c in range(A):
            pred[c][row[c]].append(s)

    blocks = {}
    block_of = [0] * n
    nxt = [0]

    def new_block(S):
        bid = nxt[0]
        nxt[0] += 1
        blocks[bid] = S
        for s in S:
            block_of[s] = bid
        return bid

    acc = set(s for s in range(n) if accept[s])
    non = set(s for s in range(n) if not accept[s])
    if acc:
        new_block(acc)
    if non:
        new_block(non)

    Wd = deque()
    inW = set()

    def addW(bid):
        if bid not in inW:
            inW.add(bid)
            Wd.append(bid)

    for bid in list(blocks.keys()):
        addW(bid)

    while Wd:
        xid = Wd.popleft()
        if xid not in inW:
            continue
        inW.discard(xid)
        X = blocks.get(xid)
        if X is None:
            continue
        for c in range(A):
            Y = set()
            pc = pred[c]
            for t in X:
                pl = pc[t]
                if pl:
                    Y.update(pl)
            if not Y:
                continue
            touched = {}
            for s in Y:
                b = block_of[s]
                if b in touched:
                    touched[b].add(s)
                else:
                    touched[b] = {s}
            for b, inter in touched.items():
                B = blocks[b]
                if len(inter) == len(B):
                    continue
                diff = B - inter
                del blocks[b]
                ib = new_block(inter)
                db = new_block(diff)
                if b in inW:
                    inW.discard(b)
                    addW(ib)
                    addW(db)
                else:
                    if len(inter) <= len(diff):
                        addW(ib)
                    else:
                        addW(db)
    return blocks, block_of


def minimize_and_canonical(n, A, trans, accept):
    blocks, block_of = hopcroft(n, A, trans, accept)

    start_bid = block_of[0]
    bid_to_new = {start_bid: 0}
    order = [start_bid]
    dq = deque([start_bid])
    while dq:
        b = dq.popleft()
        rep = next(iter(blocks[b]))
        row = trans[rep]
        for c in range(A):
            nb = block_of[row[c]]
            if nb not in bid_to_new:
                bid_to_new[nb] = len(order)
                order.append(nb)
                dq.append(nb)

    k = len(order)
    new_trans = [[0] * A for _ in range(k)]
    new_accept = [False] * k
    for newidx, b in enumerate(order):
        rep = next(iter(blocks[b]))
        new_accept[newidx] = accept[rep]
        row = trans[rep]
        nrow = new_trans[newidx]
        for c in range(A):
            nrow[c] = bid_to_new[block_of[row[c]]]
    return new_trans, new_accept


def compute_distance(k, A, trans, accept):
    dist = [None] * k
    dq = deque()
    for s in range(k):
        if accept[s]:
            dist[s] = 0
            dq.append(s)
    rev = [[] for _ in range(k)]
    for s in range(k):
        row = trans[s]
        for c in range(A):
            rev[row[c]].append(s)
    while dq:
        s = dq.popleft()
        ds = dist[s] + 1
        for p in rev[s]:
            if dist[p] is None:
                dist[p] = ds
                dq.append(p)
    return dist


# ---------------------------------------------------------------------------
# Top-level compilation
# ---------------------------------------------------------------------------

def compile_bundle(data):
    global global_tree
    services, rules, queries, stats = validate_request(data)
    A = len(services)
    service_index = {s: i for i, s in enumerate(services)}

    # distinct atoms, sorted for determinism
    atoms = sorted(stats.atoms, key=lambda ap: (ap[0], ap[1]))
    atom_index = {ap: i for i, ap in enumerate(atoms)}

    allow_children = []
    drop_children = []
    for rule in rules:
        tree = build_tree(rule['when'], atom_index)
        if rule['action'] == 'allow':
            allow_children.append(tree)
        else:
            drop_children.append(tree)

    global_tree = ('and', [('or', allow_children), ('not', ('or', drop_children))])

    trans, accept = build_product(atoms, service_index, A)

    new_trans, new_accept = minimize_and_canonical(len(trans), A, trans, accept)
    dist = compute_distance(len(new_trans), A, new_trans, new_accept)

    qout = []
    for q in queries:
        s = 0
        for tok in q:
            s = new_trans[s][service_index[tok]]
        qout.append({'state': s, 'allow': new_accept[s], 'distance': dist[s]})

    return {
        'ok': True,
        'dfa': {
            'start': 0,
            'accept': new_accept,
            'next': new_trans,
            'distance': dist,
        },
        'queries': qout,
    }


def process_line(raw):
    try:
        if len(raw) > 1048576:
            raise WireError('E_LIMIT')
        try:
            text = raw.decode('utf-8')
        except UnicodeDecodeError:
            raise WireError('E_JSON')
        if not depth_within_limit(text):
            raise WireError('E_LIMIT')
        data = decode_json(text)
        return compile_bundle(data)
    except WireError as e:
        return {'ok': False, 'error': e.code}
    except Exception:
        return {'ok': False, 'error': 'E_JSON'}


def main():
    data = sys.stdin.buffer.read()
    if not data:
        return
    lines = data.split(b'\n')
    if lines and lines[-1] == b'':
        lines.pop()
    out = []
    for raw in lines:
        res = process_line(raw)
        out.append(json.dumps(res, separators=(',', ':')))
    sys.stdout.write('\n'.join(out) + '\n')
    sys.stdout.flush()


if __name__ == '__main__':
    main()
